def _observe_crop(width, height, x_offset, y_offset, expected_width, expected_height, expected_x_offset, expected_y_offset, case):
    actual = (width, height, x_offset, y_offset)
    expected = (expected_width, expected_height, expected_x_offset, expected_y_offset)
    if any((type(value) is not int for value in actual + expected)):
        raise TypeError('Q crop scalar oracle requires native Python INT outputs and expected values')
    if actual != expected:
        raise AssertionError(f'Q crop {case}: actual {actual} != expected {expected}')
    return {'case': case, 'actual_width_height_x_offset_y_offset': list(actual), 'expected_width_height_x_offset_y_offset': list(expected), 'actual_types': [type(value).__name__ for value in actual], 'all_four_scalars_equal': True}

